# New transform that preserves background
def transform(grid):
    rows = len(grid)
    if rows == 0:
        return []
    cols = len(grid[0])
    output = [row[:] for row in grid]  # Keep input with background

    markers = []
    bg = 6
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != bg:
                markers.append((r, c))

    for mr, mc in markers:
        # Apply pattern, but only if bg cell
        if mr - 1 >= 0:
            if output[mr-1][mc] == bg:
                output[mr-1][mc] = 8
            if output[mr-1][mc+1] == bg:
                output[mr-1][mc+1] = 5
        if output[mr][mc] == bg:
            output[mr][mc] = 0  # Marker position becomes 0
        if output[mr][mc+1] == bg:
            output[mr][mc+1] = 5

        abs_r, abs_c = mr, mc
        if abs_r + 1 < rows:
            if output[abs_r+1][abs_c] == bg:
                if abs_r % 3 == 2 and abs_c % 2 == 0:
                    output[abs_r+1][abs_c] = 7
                else:
                    output[abs_r+1][abs_c] = 6
            if abs_r + 1 < rows and abs_c + 1 < cols:
                if output[abs_r+1][abs_c+1] == bg:
                    if abs_r % 3 == 2 and abs_c % 2 == 0:
                        output[abs_r+1][abs_c+1] = 6
                    elif abs_r % 3 == 2 and abs_c % 2 == 1:
                        output[abs_r+1][abs_c+1] = 5
                    else:
                        output[abs_r+1][abs_c+1] = 6

    return output

